/* Named external assignees have no login account. */
(()=>{'use strict';const shared=document.body.classList.contains('shared-app'),q=s=>document.querySelector(s),allowed=()=>shared?management():manager();
function externalForm(m=null){if(!allowed())return;const d=q(shared?'#sharedDialog':'#details'),root=q(shared?'#sharedDetail':'#detailBody');if(shared)selectedTask=null;else selectedRichTask=null;root.innerHTML='<div class="shared-task-head"><h2>فرد بدون پنل</h2><button type="button" class="secondary" id="externalClose">بستن</button></div><p class="shared-meta">این نام در مسئول‌ها قابل انتخاب است؛ حساب ورود، ایمیل دعوت یا دسترسی ایجاد نمی‌شود.</p><form id="externalForm"><label>نام فرد / پیمانکار<input name="name" required maxlength="100" value="'+esc(m?.name||'')+'"></label><label>سمت یا شرکت<input name="title" required maxlength="100" value="'+esc((shared?m?.title:m?.role)||'')+'"></label><label class="checkbox-choice"><input name="active" type="checkbox" '+(m?.active!==false?'checked':'')+'>قابل انتخاب در ارجاع</label><button class="primary">ذخیره نام</button></form>';if(!d.open)d.showModal();q('#externalClose').onclick=()=>d.close();q('#externalForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button'),f=new FormData(e.target);b.disabled=true;try{if(shared){await rpc('sm_save_external_member',{p_project:project.id,p_id:m?.id||null,p_name:f.get('name').trim(),p_title:f.get('title').trim(),p_active:f.has('active')});await refresh()}else{const v={name:f.get('name').trim(),role:f.get('title').trim(),access:'member',external:true,active:f.has('active'),email:'',legacy:false};if(m)Object.assign(m,v);else members.push({id:crypto.randomUUID(),...v});localStorage.setItem('daraei-members-v1',JSON.stringify(members));syncMemberOptions();render()}d.close();(shared?message:toast)('نام بدون ساخت حساب ورود ثبت شد.')}catch(err){(shared?message:toast)(shared?failure(err):err.message)}finally{b.disabled=false}}}
const oldMembers=renderMembers;renderMembers=function(...args){oldMembers(...args);if(!allowed())return;const root=q(shared?'#sharedContent':'#workspace');if(!root)return;const b=document.createElement('button');b.className='secondary';b.id='addExternalContact';b.textContent='＋ افزودن فرد بدون پنل';b.onclick=()=>externalForm();root.prepend(b)};
if(shared){const oldForm=memberForm;memberForm=function(m=null){if(m?.external)return externalForm(m);return oldForm(m)}}else{const oldForm=openMember;openMember=function(i=null){if(i!==null&&members[i]?.external)return externalForm(members[i]);return oldForm(i)}}
})();
